const dlCl = s => f4LongCloses(s) || (state.map[s] && state.map[s].closes) || (state.inst[s] && state.inst[s].closes) || [];
function dlRetMap(s, n = 260) { const c = dlCl(s), m = new Map(); for (let i = Math.max(1, c.length - n); i < c.length; i++) { const a = +c[i - 1][1], b = +c[i][1]; if (a > 0 && b > 0) { const r = Math.log(b / a); if (Math.abs(r) < 0.45) m.set(String(c[i][0]).slice(0, 10), r); } } return m; }
function dlCorrMaps(a, b) { const x = [], y = []; for (const [d, r] of a) { const v = b.get(d); if (v !== undefined) { x.push(r); y.push(v); } } if (x.length < 60) return null; const mx = x.reduce((s, v) => s + v, 0) / x.length, my = y.reduce((s, v) => s + v, 0) / y.length; let c = 0, vx = 0, vy = 0; for (let i = 0; i < x.length; i++) { c += (x[i] - mx) * (y[i] - my); vx += (x[i] - mx) ** 2; vy += (y[i] - my) ** 2; } return vx && vy ? c / Math.sqrt(vx * vy) : null; }
