  const pv = [...pr.values()], sdp = pv.length > 20 ? Math.sqrt(pv.reduce((a, v) => a + v * v, 0) / pv.length - (pv.reduce((a, v) => a + v, 0) / pv.length) ** 2) * Math.sqrt(252) * 100 : 25;
