  const fx = D.bal('fxpos'), eq = D.bal('eq'); if (!D.us && fx < 0 && eq > 0 && -fx / eq > 0.2) add('debt', 6, DL(`Net short foreign-currency position of ${ptBig(fx, 'TRY')} (${Math.round(-fx / eq * 100)}% of equity).`, `Özkaynağın %${Math.round(-fx / eq * 100)}’i kadar (${ptBig(fx, 'TL')}) net kısa döviz pozisyonu.`), DL('the lira stays stable', 'TL istikrarlı kalır'), DL('USD/TRY rising more than 10% in a quarter', 'bir çeyrekte USD/TRY’nin %10’dan fazla yükselmesi'));
